package economy

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"strconv"
	"sync"
)

// kart-tanks.json is the 卡丁城 fuel tank of every kart (FUEL.md 2),
// generated by client/tools/export-kart-tanks.mjs from the bounding box of
// each kart's model: the bigger the kart, the bigger its tank. Never edit
// it by hand.
//
//go:embed kart-tanks.json
var embeddedTanks []byte

// Tank size classes, smallest first.
const (
	TankSmall  = "small"
	TankMedium = "medium"
	TankLarge  = "large"
	TankHuge   = "huge"
)

// TankClassNames are the classes as the game shows them.
var TankClassNames = map[string]string{TankSmall: "小型", TankMedium: "中型", TankLarge: "大型", TankHuge: "巨型"}

// DefaultTankLiters is the tank of a kart the table does not list.
const DefaultTankLiters = 40

// Tank is one kart's entry.
type Tank struct {
	ItemID     int     `json:"itemId,omitempty"`
	Key        string  `json:"key,omitempty"` // system karts: the systemKart name
	InternalID string  `json:"internalId"`
	Name       string  `json:"name"`
	Length     float64 `json:"length"`
	Width      float64 `json:"width"`
	Height     float64 `json:"height"`
	// Capacity is in litres.
	Capacity  int    `json:"capacity"`
	SizeClass string `json:"sizeClass"`
	Measured  bool   `json:"measured"`
}

// Tanks is the parsed table.
type Tanks struct {
	Version int    `json:"version"`
	Formula string `json:"formula"`
	Karts   []Tank `json:"karts"`
	System  []Tank `json:"system"`

	byItem   map[int]int
	bySystem map[string]int
}

// ParseTanks parses and checks a tank table.
func ParseTanks(raw []byte) (*Tanks, error) {
	var t Tanks
	if err := json.Unmarshal(raw, &t); err != nil {
		return nil, fmt.Errorf("kart-tanks.json: %w", err)
	}
	t.byItem = make(map[int]int, len(t.Karts))
	t.bySystem = make(map[string]int, len(t.System))
	check := func(tank Tank, where string) error {
		if tank.Capacity <= 0 || tank.Capacity > 1000 {
			return fmt.Errorf("kart-tanks.json: %s capacity %d", where, tank.Capacity)
		}
		if _, ok := TankClassNames[tank.SizeClass]; !ok {
			return fmt.Errorf("kart-tanks.json: %s size class %q", where, tank.SizeClass)
		}
		return nil
	}
	for i, tank := range t.Karts {
		where := "item " + strconv.Itoa(tank.ItemID)
		if tank.ItemID <= 0 {
			return nil, fmt.Errorf("kart-tanks.json: kart %d without itemId", i)
		}
		if _, dup := t.byItem[tank.ItemID]; dup {
			return nil, fmt.Errorf("kart-tanks.json: %s listed twice", where)
		}
		if err := check(tank, where); err != nil {
			return nil, err
		}
		t.byItem[tank.ItemID] = i
	}
	for i, tank := range t.System {
		where := "system kart " + tank.Key
		if tank.Key == "" {
			return nil, fmt.Errorf("kart-tanks.json: system kart %d without key", i)
		}
		if _, dup := t.bySystem[tank.Key]; dup {
			return nil, fmt.Errorf("kart-tanks.json: %s listed twice", where)
		}
		if err := check(tank, where); err != nil {
			return nil, err
		}
		t.bySystem[tank.Key] = i
	}
	return &t, nil
}

// ForItem returns the tank of a catalog kart.
func (t *Tanks) ForItem(itemID int) (Tank, bool) {
	if i, ok := t.byItem[itemID]; ok {
		return t.Karts[i], true
	}
	return Tank{}, false
}

// ForSystem returns the tank of a system kart (itemId 0, named by key).
func (t *Tanks) ForSystem(key string) (Tank, bool) {
	if i, ok := t.bySystem[key]; ok {
		return t.System[i], true
	}
	return Tank{}, false
}

var loadTanks = sync.OnceValues(func() (*Tanks, error) { return ParseTanks(embeddedTanks) })

// DefaultTanks returns the embedded table, parsed once per process.
func DefaultTanks() (*Tanks, error) { return loadTanks() }
